#!/usr/bin/env bash
# Regenerates the dashboard's world map from Natural Earth's 1:110m countries
# (public domain): one SVG path per country, keyed by ISO 3166 code, in the
# Equal Earth projection.
#
#   ./update-world.sh            # Natural Earth v5.1.2
#   ./update-world.sh v5.1.2     # a particular release
#
# Vendored like the editor, so building WordMaker needs no network access.
set -euo pipefail

cd "$(dirname "$0")"

release=${1:-v5.1.2}
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT

curl -fsSL -o "$work/countries.geojson" \
  "https://raw.githubusercontent.com/nvkelso/natural-earth-vector/$release/geojson/ne_110m_admin_0_countries.geojson"
npm install --silent --prefix "$work" d3-geo@3 >/dev/null

cat > "$work/generate.mjs" <<'JS'
import { readFileSync, writeFileSync } from "node:fs";
import { geoEqualEarth, geoPath } from "d3-geo";

const [input, output, release] = process.argv.slice(2);
const world = JSON.parse(readFileSync(input, "utf8"));
// Antarctica has no visitors worth the space.
const features = world.features.filter((f) => f.properties.ISO_A2_EH !== "AQ");
const width = 960;
const projection = geoEqualEarth().fitWidth(width, { type: "FeatureCollection", features });
const path = geoPath(projection).digits(1);
const height = Math.ceil(path.bounds({ type: "FeatureCollection", features })[1][1]);

const countries = {};
for (const feature of features) {
  const code = feature.properties.ISO_A2_EH;
  if (!/^[A-Z]{2}$/.test(code)) continue;
  countries[code] = (countries[code] ?? "") + path(feature);
}
writeFileSync(
  output,
  `// Generated by vendor/update-world.sh from Natural Earth ${release} 1:110m\n` +
    `// admin-0 countries (public domain), Equal Earth projection.\n` +
    `export const width = ${width};\nexport const height = ${height};\n` +
    `export const countries = ${JSON.stringify(countries)};\n`,
);
console.log(`${Object.keys(countries).length} countries, ${width}x${height}`);
JS
node "$work/generate.mjs" "$work/countries.geojson" world/world.js "$release"
echo "Natural Earth $release" > world/VERSION
echo "world map generated from Natural Earth $release"
